using System.Globalization;
using System.Text;
using GlpiPilot.Core;

var checks = 0;
void Check(bool condition, string name) { if (!condition) throw new Exception("ÉCHEC : " + name); Console.WriteLine("OK " + name); checks++; }
void Reject(Action action, string name) { try { action(); } catch (InvalidDataException) { Check(true, name); return; } throw new Exception("ÉCHEC (non rejeté) : " + name); }
DateTimeOffset U(string date) => DateTimeOffset.Parse(date, CultureInfo.InvariantCulture);
CalendarIntervention Entry(string start = "2026-10-26T09:00", string end = "2026-10-26T10:30") => new() { Title = "Intervention libre", StartLocal = start, EndLocal = end, TimeZoneId = "Europe/Paris" };
CalendarOccurrence[] View(params CalendarIntervention[] entries) => InterventionCalendarService.Expand(entries, U("2026-10-01T00:00Z"), U("2026-12-01T00:00Z")).ToArray();
CalendarResource Tech(string key = "a") => new() { Key = key, Label = "Technicien " + key, TimeZoneId = "Europe/Paris", WorkPeriods = Enumerable.Range(1, 5).SelectMany(day => new[] { new CalendarWorkPeriod { Day = day, StartMinute = 480, EndMinute = 720, CapacityMinutes = 240 }, new CalendarWorkPeriod { Day = day, StartMinute = 780, EndMinute = 1020, CapacityMinutes = 240 } }).ToList() };
var free = Entry(); var expanded = View(free);
Check(expanded.Length == 1 && expanded[0].Tickets.Count == 0 && expanded[0].ParticipantKeys.Count == 0, "intervention libre sans relevé ni affectation");
Check(expanded[0].StartUtc == U("2026-10-26T08:00Z") && expanded[0].DurationMinutes == 90, "heure locale convertie en intervalle UTC exact");
var work = Entry(); work.ParticipantKeys = ["a", "b"];
work.Tickets = Enumerable.Range(1, 3).Select(i => new CalendarTicketReference { Key = "installation-a:" + i, Installation = "https://glpi.example.test/", Id = i.ToString(), Title = "Ticket " + i }).ToList();
var workView = View(work); var summary = InterventionCalendarService.Summarize(workView.Concat(workView));
Check(summary.Interventions == 1 && summary.LinkedTickets == 3 && summary.PersonHours == 3 && summary.InterventionHours == 1.5, "co-intervention : 1 intervention, 3 tickets, 3 heures-personnes sans doublon");
var anotherInstall = work.Copy(); anotherInstall.Tickets.Add(new() { Key = "installation-b:1", Installation = "https://another.example.test/", Id = "1" }); InterventionCalendarService.Validate(anotherInstall);
Check(anotherInstall.Tickets.Count == 4, "ID numérique identique sur deux installations distinctes conservé");
Reject(() => { var bad = work.Copy(); bad.Tickets.Add(bad.Tickets[0].Copy()); InterventionCalendarService.Validate(bad); }, "référence de ticket dupliquée rejetée");
Reject(() => { var bad = work.Copy(); bad.Tickets[0].Installation = ""; InterventionCalendarService.Validate(bad); }, "installation absente rejetée");
Reject(() => { var bad = work.Copy(); bad.ParticipantKeys.Add("a"); InterventionCalendarService.Validate(bad); }, "participant dupliqué rejeté");
Reject(() => { var bad = work.Copy(); bad.EndLocal = bad.StartLocal; InterventionCalendarService.Validate(bad); }, "durée nulle rejetée");
var midnight = Entry("2026-10-26T23:30", "2026-10-27T01:00"); Check(View(midnight)[0].DurationMinutes == 90, "intervention traversant minuit");
Check(InterventionCalendarService.Expand([free], U("2026-10-26T09:30Z"), U("2026-10-27T00:00Z")).Count == 0, "borne de fin exclusive sans doublon de journée");
Reject(() => InterventionCalendarService.Validate(Entry("2026-03-29T02:30", "2026-03-29T03:30")), "heure inexistante Europe/Paris rejetée");
Reject(() => InterventionCalendarService.Validate(Entry("2026-10-25T02:15", "2026-10-25T02:45")), "heure répétée sans choix UTC rejetée");
var autumn = Entry("2026-10-25T02:15", "2026-10-25T02:45"); autumn.StartOffsetMinutes = 120; autumn.EndOffsetMinutes = 60;
Check(View(autumn)[0].DurationMinutes == 90, "heure répétée : deux décalages explicites conservent 90 minutes réelles");
var folded = Entry("2026-10-25T02:45", "2026-10-25T02:15"); folded.StartOffsetMinutes = 120; folded.EndOffsetMinutes = 60;
Check(View(folded)[0].DurationMinutes == 30, "retour de l’horloge : fin locale antérieure mais durée réelle positive");
var daily = Entry("2026-10-23T09:00", "2026-10-23T10:00"); daily.Recurrence = new() { Frequency = "daily", Count = 5 }; daily.StartOffsetMinutes = 120; daily.EndOffsetMinutes = 120;
var days = View(daily); Check(days.Length == 5 && days[0].StartUtc.Hour == 7 && days[^1].StartUtc.Hour == 8 && days.All(value => value.StartLocal.EndsWith("09:00")), "récurrence garde l’heure locale à travers le changement d’heure");
var weekly = Entry(); weekly.Recurrence = new() { Frequency = "weekly", WeekDays = [1, 3], Count = 4 }; var weeks = View(weekly);
Check(weeks.Length == 4 && weeks.Select(value => value.StartLocal[..10]).SequenceEqual(new[] { "2026-10-26", "2026-10-28", "2026-11-02", "2026-11-04" }), "série hebdomadaire à plusieurs jours et limite de nombre");
var fortnight = weekly.Copy(); fortnight.Recurrence!.Interval = 2; Check(View(fortnight)[2].StartLocal.StartsWith("2026-11-09"), "intervalle de deux semaines relatif à la semaine d’ancrage");
var monthly = Entry("2026-01-31T09:00", "2026-01-31T10:00"); monthly.Recurrence = new() { Frequency = "monthly", Count = 3 };
var months = InterventionCalendarService.Expand([monthly], U("2026-01-01Z"), U("2026-07-01Z")); Check(months.Select(value => value.StartLocal[..10]).SequenceEqual(new[] { "2026-01-31", "2026-03-31", "2026-05-31" }), "récurrence mensuelle saute les dates inexistantes sans les déplacer");
var until = daily.Copy(); until.Recurrence!.Count = null; until.Recurrence.Until = "2026-10-25"; Check(View(until).Length == 3, "date de fin de série inclusive");
var moved = Entry("2026-11-10T14:00", "2026-11-10T15:00"); var exception = InterventionCalendarService.WithOccurrence(weekly, "2026-10-28T09:00", moved);
var moveView = View(exception); Check(moveView.Length == 4 && moveView.Single(value => value.OriginalStartLocal == "2026-10-28T09:00").StartLocal == "2026-11-10T14:00", "exception déplace exactement une occurrence");
Check(moveView.Single(value => value.OriginalStartLocal == "2026-10-28T09:00").Key == weeks[1].Key, "identité stable d’une occurrence déplacée");
var inOnly = InterventionCalendarService.Expand([exception], U("2026-11-10T00:00Z"), U("2026-11-11T00:00Z")); Check(inOnly.Count == 1, "exception déplacée visible même si sa date d’origine est hors fenêtre");
var cancelled = InterventionCalendarService.WithOccurrence(exception, "2026-11-02T09:00", null, true); Check(View(cancelled).Single(value => value.OriginalStartLocal == "2026-11-02T09:00").State == "cancelled", "annulation d’occurrence conservant son identité");
var splitReplacement = weekly.Copy(); splitReplacement.StartLocal = "2026-11-02T14:00"; splitReplacement.EndLocal = "2026-11-02T15:30";
var split = InterventionCalendarService.SplitFollowing(weekly, "2026-11-02T09:00", splitReplacement);
Check(View(split.Before).Length == 2 && View(split.Following).Length == 2 && split.Following.Id != weekly.Id && View(split.Before).All(value => value.StartLocal.EndsWith("09:00")), "modifier cette occurrence et les suivantes préserve le passé et limite la nouvelle série");
Check(View(split.Following).Select(value => value.Key).SequenceEqual(weeks.Skip(2).Select(value => value.Key)), "séparation de série conserve les identités des occurrences futures");
var rescheduled = free.Copy(); rescheduled.StartLocal = "2026-10-27T14:00"; rescheduled.EndLocal = "2026-10-27T15:30";
Check(View(rescheduled)[0].Key == expanded[0].Key, "déplacement d’une intervention libre conserve son identité de calendrier");
var renamedSeries = weekly.Copy(); renamedSeries.StartLocal = "2026-10-26T14:00"; renamedSeries.EndLocal = "2026-10-26T15:30";
var rebase = InterventionCalendarService.WithSeries(exception, renamedSeries);
Check(View(rebase).Select(value => value.Key).Order().SequenceEqual(weeks.Select(value => value.Key).Order()) && View(rebase).Single(value => value.Exception).StartLocal == "2026-11-10T14:00", "changement de série conserve les identités et les déplacements individuels");
var lineageCollision = split.Following.Copy(); lineageCollision.Id = Guid.NewGuid().ToString("N");
Check(InterventionCalendarService.ExpandDetailed([split.Following, lineageCollision], U("2026-10-01Z"), U("2026-12-01Z")).Issues.Count == 2, "deux fragments concurrents de la même série produisent un diagnostic explicite");
var historic = Entry("2000-01-01T09:00", "2000-01-01T10:00"); historic.Recurrence = new() { Frequency = "daily" };
var historicView = InterventionCalendarService.Expand([historic], U("2026-10-01T00:00Z"), U("2026-11-01T00:00Z"));
Check(historicView.Count == 31 && historicView.Select(value => value.Key).Distinct().Count() == 31, "ancienne série ouverte limitée à la fenêtre demandée avec identités exactes");
var invalidWeekly = Entry("2026-10-18T02:15", "2026-10-18T02:45"); invalidWeekly.Recurrence = new() { Frequency = "weekly", Count = 3 };
var detailed = InterventionCalendarService.ExpandDetailed([invalidWeekly, free], U("2026-10-01Z"), U("2026-12-01Z")); Check(detailed.Occurrences.Count == 3 && detailed.Issues.Count == 1 && detailed.Issues[0].OriginalStartLocal == "2026-10-25T02:15", "heure récurrente ambiguë signalée sans masquer les autres rendez-vous");
var overlap = Entry("2026-10-26T10:00", "2026-10-26T11:00"); overlap.ParticipantKeys = ["b"];
var collisions = InterventionCalendarService.Conflicts(View(work, overlap), [Tech("a"), Tech("b")]); Check(collisions.Count(value => value.Kind == "overlap") == 1 && collisions.Single(value => value.Kind == "overlap").ParticipantKey == "b", "collision détectée uniquement pour le participant commun");
var adjacent = Entry("2026-10-26T10:30", "2026-10-26T11:00"); adjacent.ParticipantKeys = ["a"];
Check(!InterventionCalendarService.Conflicts(View(work, adjacent), [Tech("a"), Tech("b")]).Any(value => value.Kind == "overlap"), "rendez-vous adjacents sans faux chevauchement");
work.TravelAfterMinutes = 15; adjacent.TravelBeforeMinutes = 10;
Check(InterventionCalendarService.Conflicts(View(work, adjacent), [Tech("a"), Tech("b")]).Any(value => value.Kind == "travel"), "temps de déplacement déclaré pris en compte entre deux réservations");
var unavailable = overlap.Copy(); unavailable.Kind = "unavailability";
Check(InterventionCalendarService.Conflicts(View(work, unavailable), [Tech("a"), Tech("b")]).Any(value => value.Kind == "unavailable"), "indisponibilité collective détectée comme réservation bloquante");
Check(InterventionCalendarService.Summarize(View(work, unavailable)).Interventions == 1 && InterventionCalendarService.Summarize(View(work, unavailable)).Unavailabilities == 1, "indisponibilité séparée du nombre d’interventions");
var cancelledOverlap = overlap.Copy(); cancelledOverlap.State = "cancelled";
Check(!InterventionCalendarService.Conflicts(View(work, cancelledOverlap), [Tech("a"), Tech("b")]).Any(value => value.Kind == "overlap"), "intervention annulée libère son créneau");
var unknown = InterventionCalendarService.Conflicts(View(work), [new() { Key = "a", Label = "Sans horaires", TimeZoneId = "Europe/Paris" }]);
Check(unknown.Count(value => value.Kind == "unknownAvailability") == 2 && unknown.All(value => value.Severity == "info"), "disponibilité inconnue explicite, jamais assimilée à zéro");
var cap = Tech("a"); cap.CapacityDays = [new() { Date = "2026-10-26", MorningMinutes = 60 }];
Check(InterventionCalendarService.Conflicts(View(work), [cap, Tech("b")]).Any(value => value.Kind == "capacity"), "capacité journalière déclarée distincte du nombre de tickets");
var lunch = Entry("2026-10-26T12:15", "2026-10-26T12:45"); lunch.ParticipantKeys = ["a"];
Check(InterventionCalendarService.Conflicts(View(lunch), [Tech()]).Any(value => value.Kind == "outsideHours"), "pause hors plages de présence signalée");
var flexible = Tech(); flexible.WorkPeriods = [new() { Day = 1, StartMinute = 480, EndMinute = 960, CapacityMinutes = 180 }];
var concentrated = Entry("2026-10-26T09:00", "2026-10-26T12:00"); concentrated.ParticipantKeys = ["a"];
Check(!InterventionCalendarService.Conflicts(View(concentrated), [flexible]).Any(value => value.Kind == "capacity"), "capacité de plage non répartie arbitrairement entre matin et après-midi");
var earlyTravel = Entry("2026-10-26T08:00", "2026-10-26T09:00"); earlyTravel.ParticipantKeys = ["a"]; earlyTravel.TravelBeforeMinutes = 30;
Check(InterventionCalendarService.Conflicts(View(earlyTravel), [Tech()]).Any(value => value.Kind == "outsideHours"), "déplacement avant l’ouverture de la plage de présence signalé");
var tour = View(overlap)[0]; tour.Source = "tour"; tour.Key = "tour:stable:stop:stable"; tour.TourId = "stable"; tour.ReadOnly = true;
Check(InterventionCalendarService.Conflicts(View(work).Append(tour).ToArray(), [Tech("a"), Tech("b")]).Any(value => value.Kind == "overlap"), "conflit entre une visite de tournée et une intervention indépendante");
var proposed = Entry(); proposed.ParticipantKeys = ["a"]; var suggestions = InterventionCalendarService.SuggestSlots(proposed, View(work), [Tech()], U("2026-10-26T07:00Z"), U("2026-10-27T18:00Z"), 4);
Check(suggestions.Count == 4 && suggestions.All(value => value.Warnings.Count == 0 && (value.EndUtc <= View(work)[0].StartUtc || value.StartUtc >= View(work)[0].EndUtc.AddMinutes(15))), "suggestions de créneaux respectent présence, chevauchements et déplacement");
var unknownSuggestions = InterventionCalendarService.SuggestSlots(proposed, [], [], U("2026-10-26T07:00Z"), U("2026-10-26T18:00Z"), 2); Check(unknownSuggestions.Count == 2 && unknownSuggestions.All(value => value.Warnings.Count > 0), "proposition avec disponibilité inconnue conserve son avertissement");
var ics = InterventionCalendarService.ExportIcs(moveView, createdAt: U("2026-10-01Z")); var icsAgain = InterventionCalendarService.ExportIcs(View(weekly), createdAt: U("2026-10-01Z"));
string UidFor(string source, string start) => source.Split("BEGIN:VEVENT").First(value => value.Contains(start)).Split("\r\n").First(value => value.StartsWith("UID:"));
Check(UidFor(ics, "DTSTART:20261110T130000Z") == UidFor(icsAgain, "DTSTART:20261028T080000Z"), "UID ICS stable quand une occurrence change d’horaire");
var unicode = Entry(); unicode.Title = string.Concat(Enumerable.Repeat("é😀", 50)); var unicodeIcs = InterventionCalendarService.ExportIcs(View(unicode));
Check(unicodeIcs.Split("\r\n").All(line => Encoding.UTF8.GetByteCount(line) <= 75) && !unicodeIcs.Contains('\uFFFD'), "pliage ICS à 75 octets sans couper les caractères Unicode");
var allDay = Entry("2026-10-26T00:00", "2026-10-27T00:00"); allDay.AllDay = true;
var allDayIcs = InterventionCalendarService.ExportIcs(View(allDay)); Check(allDayIcs.Contains("DTSTART;VALUE=DATE:20261026") && allDayIcs.Contains("DTEND;VALUE=DATE:20261027"), "ICS journée entière avec fin exclusive");
var injection = Entry(); injection.Title = "<script>alert('x')</script>"; injection.Notes = "<img src=x onerror=alert(1)>";
var html = InterventionCalendarService.ExportHtml(View(injection)); Check(!html.Contains("<script>") && html.Contains("&lt;script&gt;") && !html.Contains("<img"), "fiche imprimable encode les contenus métier");
var remind = Entry(); remind.ReminderMinutes = 15; Check(InterventionCalendarService.ExportIcs(View(remind)).Contains("TRIGGER:-PT15M"), "rappel ICS attaché à l’intervention");
Check(InterventionCalendarService.ExportIcs(View(cancelled)).Contains("STATUS:CANCELLED"), "annulation exportée avec identité conservée");
var cancelledToken = new CancellationToken(true); try { InterventionCalendarService.Expand([weekly], U("2026-10-01Z"), U("2026-12-01Z"), cancelledToken); throw new Exception("Annulation ignorée"); } catch (OperationCanceledException) { Check(true, "calcul annulable"); }
Reject(() => InterventionCalendarService.Expand([weekly], U("2026-01-01Z"), U("2030-01-01Z")), "période démesurée rejetée");
Console.WriteLine($"{checks}/{checks} contrôles calendrier réussis.");
